head.script:

        var src;
        var maxNum = 5;
        var currentNum = 0;

        function fn_closeMsg(){
        	//alert("메세지"); 
     		return true;
     		//return confirm("do you close this window?"); // 확인, 취소 버튼이 있는 메세지 창 사용.  
     		//return false; // 무조건 닫기 취소. 
		} 

		createWindow = function(winId, iconUrl, src, title, id, openAction, closeAction) {
			currentNum = windowContainer1.currentWindowNum;
            setTimeout( function() {
                windowContainer1.createWindow( winId, iconUrl, src, title, id, openAction, closeAction);
            }, 100);

		};
		createWindow("WIN1", null, "windowContainer_arrange_WEFF-779_(WSQ-4193)_sub1.xml", "page001", "P0001", "newWindow", "fn_closeMsg");
		createWindow("WIN2", null, "windowContainer_arrange_WEFF-779_(WSQ-4193)_sub2.xml", "page002", "P0002", "newWindow", "fn_closeMsg");
		createWindow("WIN3", null, "windowContainer_arrange_WEFF-779_(WSQ-4193)_sub3.xml", "page003", "P0003", "newWindow", "fn_closeMsg");
        createWindow("WIN4", null, "windowContainer_arrange_WEFF-779_(WSQ-4193)_sub3.xml", "page004", "P0004", "newWindow", "fn_closeMsg");

		scwin.trigger4_onclick = function(e) {
			windowContainer1.setArrangeWindows("vertical", ["P0002", "P0001", "P0004"]);
		};

		scwin.trigger5_onclick = function(e) {
			windowContainer1.setArrangeWindows("vertical", ["P0001", "P0003", "P0002"]);
		};

		scwin.trigger6_onclick = function(e) {
			windowContainer1.setArrangeWindows("horizontal", ["P0002", "P0001", "P0004"]);
		};

        scwin.trigger7_onclick = function(e) {
            windowContainer1.setArrangeWindows("vertical", ["P0004", "P0001", "P0003"]);
        };

        scwin.trigger8_onclick = function(e) {
            windowContainer1.setArrangeWindows("vertical", ["P0003", "P0001", "P0002"]);
        };

        scwin.trigger9_onclick = function(e) {
            windowContainer1.setArrangeWindows("vertical", ["P0001", "P0002", "P0003"]);
        };

		scwin.checkVal1 = function() {
			return WebSquare.wUnit.getJq('#windowContainer1_subWindow0').offset().left > 200 && WebSquare.wUnit.getJq('#windowContainer1_subWindow3').offset().left > 450;
		}
		scwin.unitTest = function() {
			//Unit
			WebSquare.wUnit.start();
			WebSquare.wUnit.addCommand("pause", "500");
			WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger4').click()");
			WebSquare.wUnit.addCommand("pause", "400");
			WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
			WebSquare.wUnit.addCommand("pause", "500");
			//Run test and stop
			WebSquare.wUnit.run();
			WebSquare.wUnit.stop();
		}	
		scwin.unitTest()
